import{_ as a,o as r,c as o,a2 as e}from"./chunks/framework.Bqa2y7hU.js";const b=JSON.parse('{"title":"订阅 · 卡密 · 充值","description":"套餐与额度、余额购买续费、卡密兑换与余额充值。","frontmatter":{"title":"订阅 · 卡密 · 充值","description":"套餐与额度、余额购买续费、卡密兑换与余额充值。"},"headers":[],"relativePath":"console/billing.md","filePath":"console/billing.md","lastUpdated":1789268494000}'),l={name:"console/billing.md"};function d(i,t,n,s,h,c){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="订阅-·-卡密-·-充值-💳" tabindex="-1">订阅 · 卡密 · 充值 💳 <a class="header-anchor" href="#订阅-·-卡密-·-充值-💳" aria-label="Permalink to &quot;订阅 · 卡密 · 充值 💳&quot;">​</a></h1><p>这页讲清楚三件事：<strong>套餐决定你能用多少</strong>、<strong>怎么用余额买或续</strong>、<strong>钱怎么进来</strong>（卡密兑换或在线充值）。</p><p>额度用满是新手最常撞的墙——机器人位和插件位都由套餐决定，所以先把这页看完，再去建机器人会顺很多。</p><h2 id="_1-套餐决定什么" tabindex="-1">1. 套餐决定什么 <a class="header-anchor" href="#_1-套餐决定什么" aria-label="Permalink to &quot;1. 套餐决定什么&quot;">​</a></h2><p>套餐是你在控制台的「使用许可」，它直接决定两个数字：</p><table tabindex="0"><thead><tr><th>套餐决定</th><th>影响</th></tr></thead><tbody><tr><td>机器人位</td><td>你最多能建几台机器人</td></tr><tr><td>插件位</td><td>你最多能装几份插件（同一插件装到三台机器人上算三份）</td></tr></tbody></table><p>套餐按计费模式分几类：</p><table tabindex="0"><thead><tr><th>计费模式</th><th>说明</th></tr></thead><tbody><tr><td>按月</td><td>到期后需要续费才能继续使用</td></tr><tr><td>按年</td><td>同上，周期为一年</td></tr><tr><td>永久</td><td>一次性购买，长期有效</td></tr></tbody></table><p>具体有哪些套餐、各自多少机器人位与插件位、价格多少，以「订阅中心」页面上实际列出的为准——不同服务商上架的套餐不一样。</p><h2 id="_2-用余额购买或续费" tabindex="-1">2. 用余额购买或续费 <a class="header-anchor" href="#_2-用余额购买或续费" aria-label="Permalink to &quot;2. 用余额购买或续费&quot;">​</a></h2><p>在「订阅中心」可以看到：</p><ul><li>当前套餐、到期时间</li><li>机器人位与插件位的使用情况（已用 / 总量）</li><li>可购买的套餐列表</li></ul><p>购买流程是：选套餐 → 确认 → 从<strong>余额</strong>扣款 → 套餐立即生效。</p><div class="tip custom-block"><p class="custom-block-title">余额支付是事务性的</p><p>购买和续费走的是事务性扣款：要么「扣款成功且套餐生效」，要么「整体失败、余额不动」。<strong>不会出现「钱扣了但套餐没开通」这种情况。</strong></p><p>如果你认为遇到了账目不一致，先刷新页面确认，再联系服务商核对账单即可。</p></div><p><strong>续费</strong>：在同一个页面选当前套餐续费即可，到期时间会往后叠加。快到期时控制台会有提醒，别等额度失效了才发现。</p><h2 id="_3-卡密兑换" tabindex="-1">3. 卡密兑换 <a class="header-anchor" href="#_3-卡密兑换" aria-label="Permalink to &quot;3. 卡密兑换&quot;">​</a></h2><p>卡密是服务商发放的一串兑换码，可以用来开通或延长套餐，<strong>不需要走在线支付</strong>。</p><p>兑换步骤：</p><ol><li>进「订阅中心」的卡密兑换区域</li><li>把卡密完整粘贴进去（注意不要带多余空格）</li><li>提交，兑换成功后套餐即时生效</li></ol><p>如果卡密提示无效，通常是这几种情况：已经被人用过、输入时有字符缺失、或者不是本服务商发放的卡密。核对后仍不行就联系服务商。</p><h2 id="_4-余额充值" tabindex="-1">4. 余额充值 <a class="header-anchor" href="#_4-余额充值" aria-label="Permalink to &quot;4. 余额充值&quot;">​</a></h2><p>余额是购买套餐的钱袋子。充值方式取决于服务商的配置：</p><table tabindex="0"><thead><tr><th>情况</th><th>你能用的方式</th></tr></thead><tbody><tr><td>服务商开启了在线支付</td><td>走<strong>易支付</strong>在线充值，按页面引导完成支付，成功后余额到账</td></tr><tr><td>服务商没有开启在线支付</td><td>充值入口不可用，只能用<strong>卡密兑换</strong>的方式开通套餐</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">支付入口是服务商开关控制的</p><p>页面上没有支付入口，说明服务商当前没开启在线支付，不是你的账号有问题。这时请直接联系服务商购买卡密。</p></div><p>充值到账后，余额可以用来购买或续费任何套餐，也可以留着以后再买。</p><h2 id="_5-账单与通知" tabindex="-1">5. 账单与通知 <a class="header-anchor" href="#_5-账单与通知" aria-label="Permalink to &quot;5. 账单与通知&quot;">​</a></h2><p>「用户中心」的通知中心会记录这些事件：</p><table tabindex="0"><thead><tr><th>记录类型</th><th>内容</th></tr></thead><tbody><tr><td>订阅</td><td>套餐的购买、续费、到期</td></tr><tr><td>充值</td><td>余额充值到账</td></tr><tr><td>卡密</td><td>卡密兑换的结果</td></tr><tr><td>安全事件</td><td>账号相关的安全提醒</td></tr></tbody></table><p>对不上账的时候，先翻通知中心，大部分「我买了吗、什么时候到期」的问题在这里都能自证。</p><details class="details custom-block"><summary>截图占位</summary><p>截「订阅中心」页面，露出当前套餐、到期时间、机器人位与插件位的使用条，以及套餐列表区域（价格可打码）。</p></details><h2 id="_6-常见问题" tabindex="-1">6. 常见问题 <a class="header-anchor" href="#_6-常见问题" aria-label="Permalink to &quot;6. 常见问题&quot;">​</a></h2><h3 id="症状-新建机器人-安装插件时被拒绝-提示额度相关" tabindex="-1">症状：新建机器人 / 安装插件时被拒绝，提示额度相关 <a class="header-anchor" href="#症状-新建机器人-安装插件时被拒绝-提示额度相关" aria-label="Permalink to &quot;症状：新建机器人 / 安装插件时被拒绝，提示额度相关&quot;">​</a></h3><ul><li><strong>原因</strong>：套餐配额用满了 —— 新建机器人撞的是<strong>机器人位</strong>，安装插件撞的是<strong>插件位</strong>。</li><li><strong>处理方式</strong>：删掉不用的机器人、卸载不用的插件，或升级套餐。两种情况的提示分别是 <code>bot_quota_exceeded</code> 与 <code>plugin_quota_exceeded</code>。</li></ul><h3 id="症状-充值成功但余额没变" tabindex="-1">症状：充值成功但余额没变 <a class="header-anchor" href="#症状-充值成功但余额没变" aria-label="Permalink to &quot;症状：充值成功但余额没变&quot;">​</a></h3><ul><li><strong>原因</strong>：页面没刷新，或支付回调还在路上。</li><li><strong>处理方式</strong>：稍等片刻后刷新页面；仍然没到账就带支付凭证联系服务商。</li></ul><h3 id="症状-套餐到期后机器人会怎样" tabindex="-1">症状：套餐到期后机器人会怎样 <a class="header-anchor" href="#症状-套餐到期后机器人会怎样" aria-label="Permalink to &quot;症状：套餐到期后机器人会怎样&quot;">​</a></h3><ul><li><strong>原因</strong>：套餐到期，额度不再有效。</li><li><strong>处理方式</strong>：及时续费。到期后的具体表现（机器人是否停用）由服务商的配置决定，建议在到期前就续上。</li></ul><h3 id="症状-卡密提示已被使用" tabindex="-1">症状：卡密提示已被使用 <a class="header-anchor" href="#症状-卡密提示已被使用" aria-label="Permalink to &quot;症状：卡密提示已被使用&quot;">​</a></h3><ul><li><strong>原因</strong>：卡密是一次性的，可能已被兑换过。</li><li><strong>处理方式</strong>：联系服务商核查卡密状态，不要重复尝试。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/console/overview">控制台总览</a></li><li><a href="/RuaBot.Doc/console/bots">我的机器人</a></li><li><a href="/RuaBot.Doc/console/plugins">插件市场与安装</a></li></ul>',41)])])}const u=a(l,[["render",d]]);export{b as __pageData,u as default};
